(()=>{'use strict';if(new URLSearchParams(location.search).get('embedded')==='1')return;const entries=new WeakMap();let scheduled=false,dialog,frame;const layoutStyle=document.createElement('style');layoutStyle.textContent='.angle-grid{grid-template-columns:minmax(0,2fr) repeat(3,minmax(0,1fr))!important}.angle-grid>.angle{min-width:0;max-width:100%}.angle-grid img{max-width:100%;min-width:0}.role-image-tools{display:grid!important;grid-template-columns:repeat(2,minmax(0,max-content));justify-content:center!important;width:fit-content!important;max-width:100%!important}.role-image-tools>a:last-child{grid-column:1/-1;justify-self:center}.role-image-tools>a{min-width:0;white-space:nowrap!important}.role-image-tools>a[hidden]{display:none!important}.editor.character-image-workspace{grid-template-columns:160px minmax(0,1fr)!important}.editor.character-image-workspace>.card:last-child{grid-column:1/-1}@media(min-width:1800px){.editor.character-image-workspace{grid-template-columns:175px minmax(0,1fr) 300px!important}.editor.character-image-workspace>.card:last-child{grid-column:auto}}@media(max-width:900px){.editor.character-image-workspace{grid-template-columns:minmax(0,1fr)!important}.angle-grid{grid-template-columns:repeat(2,minmax(0,1fr))!important}}';document.head.append(layoutStyle);
function source(image){try{const u=new URL(image.getAttribute('src')||image.src,location.href);return u.origin===location.origin&&/^\/api\/(?:(?:front-image|contact-sheet)\/[a-f0-9-]{36}\/image|tools\/jobs\/[a-f0-9-]{36}\/result)$/.test(u.pathname)?u.pathname+u.search:null;}catch{return null;}}
async function open(url,label,originDialog){try{if(typeof ensureProjectSaved==='function')await ensureProjectSaved();if(!dialog){dialog=document.createElement('dialog');dialog.id='roleToolDialog';dialog.style.cssText='width:96vw;max-width:1250px;height:94vh;max-height:94vh;padding:12px;box-sizing:border-box;overflow:hidden';const h=document.createElement('div');h.className='modal-head';const title=document.createElement('h2');title.id='roleToolTitle';const close=document.createElement('button');close.textContent='✕';close.setAttribute('aria-label','关闭图片工具');close.onclick=()=>dialog.close();h.append(title,close);frame=document.createElement('iframe');frame.title='角色图片工具';frame.style.cssText='display:block;width:100%;height:calc(100% - 54px);border:0;border-radius:10px;background:#101720';dialog.append(h,frame);document.body.append(dialog);}if(originDialog?.id==='shotFrameGeneratorDialog'&&originDialog.open){const projectId=data.project_id,shotId=data.shots?.[si]?.shot_id||data.shots?.[si]?.id,position=[...originDialog.querySelectorAll('[data-frame-card]')].find(c=>c.style.display!=='none')?.dataset.frameCard||'first';originDialog.close();dialog.addEventListener('close',()=>{const parent=document.getElementById('shotFrameGeneratorDialog');if(!parent||parent.open||data.project_id!==projectId||(data.shots?.[si]?.shot_id||data.shots?.[si]?.id)!==shotId)return;parent.querySelectorAll('[data-frame-card]').forEach(c=>c.style.display=c.dataset.frameCard===position?'':'none');parent.querySelector('h3').textContent='生成'+(position==='first'?'首帧':'尾帧');parent.showModal();},{once:true});}document.querySelector('#roleToolTitle').textContent=label;frame.src=url;dialog.showModal();}catch(e){if(typeof toast==='function')toast(e.message);}}
window.addEventListener('message',async e=>{if(e.origin!==location.origin||e.source!==frame?.contentWindow||e.data?.type!=='studio-role-tool-completed'||!e.data.applied_to)return;try{const t=e.data.applied_to;if(typeof data!=='undefined'&&String(data.project_id||data.local_id||data.title)===t.project_id){const r=await fetch('/api/project?id='+encodeURIComponent(t.project_id)),remote=await r.json();if(JSON.stringify(data)===lastDiskData&&!diskBusy&&!diskConflict){data=remote.project;diskRevision=remote.revision;lastDiskData=JSON.stringify(data);browserSave();render();}}dialog.close();if(typeof toast==='function')toast('生成完成，已替换对应图片，原图保留历史版本');}catch{if(typeof toast==='function')toast('结果已保存，请刷新页面查看');}});
function viewFor(c,src,image){if(c.specialReference)return 'external';const same=o=>{try{return new URL(o?.image_url||'',location.origin).pathname===src.split('?')[0];}catch{return false;}};if(same(c.versions?.[c.active]))return 'front';const entry=c.multi?.[c.multiActive??((c.multi?.length||0)-1)];for(const [a,v]of Object.entries(entry?.jobs||{}))if(same(v))return a;if(same(c.identityPortrait))return 'portrait';if(same(c.contactSheets?.[c.contactSheetActive??((c.contactSheets?.length||0)-1)]))return 'sheet';const crop=(c.singleViews||[]).find(same);if(crop?.angle)return crop.angle;const name=image.alt||'';return /侧面/.test(name)?'left':/背面/.test(name)?'back':/头像|胸像/.test(name)?'portrait':'front';}
const framing={portrait:'正面胸像特写。完整头顶、发饰、脸、颈部、双肩及衣领入画，下界在胸部。正对镜头、平视、表情自然。头部与肩膀占画面大部分，不画腰、手、腿和鞋。',front:'严格正面全身设定照。脸和身体正对镜头，头顶至鞋底完整入画，双脚清楚，双臂自然下垂，居中站立，留少量上下边距。',left:'同一人物的单个严格90度全身左侧面（true 90-degree LEFT-FACING PROFILE）。相机位于人物正侧方，以平视角度拍摄。人物的头、胸廓、肩线、骨盆、膝盖与双脚保持同向，全部朝画面左侧。头部保持自然中立，与躯干同向，不扭颈、不回头、不朝镜头转脸；视线沿鼻尖水平看向画面左侧。面部只见近侧的一只眼睛、一侧眉毛和清楚的鼻梁侧面轮廓，远侧眼睛被遮挡；不展示正面脸或四分之三侧脸。双肩在侧面投影中前后重叠，双臂自然下垂；双腿自然站直，双脚脚尖同朝左，脚跟不抬起，不交叉腿，不走台步。头顶至鞋底完整入画，保持参考图的身份、发型、服装和自然人体比例。',back:'严格全身背面。头部、身体和脚都背对镜头，不回头，不露正脸或侧脸。保留背部服装和后侧发型，完整头顶至鞋底，自然站立。',sheet:'同一角色的四区域设定合照。左侧40%为正面胸像，其余60%等分为正面全身、朝画面左的90度全身侧面、全身背面。各区域人物身份、发型、服装和比例一致。'};
function scan(){scheduled=false;for(const grid of document.querySelectorAll('.angle-grid'))grid.closest('.editor')?.classList.add('character-image-workspace');for(const image of document.querySelectorAll('img')){const src=image.closest('#portraitCandidates')||image.id==='characterImageViewerImage'?null:source(image);let r=entries.get(image);if(!src){r?.bar.remove();continue;}if(!r||!r.bar.isConnected){const bar=document.createElement('div');bar.className='role-image-tools';bar.style.cssText='display:flex;flex-wrap:wrap;align-items:center;justify-content:center;gap:7px;width:max-content;max-width:100%;align-self:center;justify-self:center;margin:8px 0;flex:0 0 auto';r={bar,links:{}};for(const[mode,label]of[['text-image','文生图'],['image-image','图生图'],['image-upscale','✦ 高清放大']]){const a=document.createElement('a');a.className='image-upscale-action';a.textContent=label;a.style.cssText='display:inline-flex;align-items:center;justify-content:center;width:max-content;max-width:100%;flex:0 0 auto;box-sizing:border-box;padding:6px 9px;border:1px solid #46665c;border-radius:8px;color:#b5e3d2;background:#1b302a;font-size:12px;text-decoration:none;line-height:1.4;cursor:pointer';a.onclick=e=>{e.preventDefault();e.stopPropagation();if(a.dataset.missingPortrait==='1'){if(typeof toast==='function')toast('请先生成当前人物的大头照，再用它生成其他角度');return;}open(a.href,label,image.closest('dialog'));};r.links[mode]=a;bar.append(a);}entries.set(image,r);if(image.id==='characterImageViewerImage')document.querySelector('#characterImageDownload')?.parentElement.append(bar);else(image.closest('a,button')||image).after(bar);}
const title=image.alt||'图片',p=new URLSearchParams({upscale_image:src,image_name:title,embedded:'1'});let c,angle;if(typeof data!=='undefined'&&typeof ci!=='undefined'){const candidate=data.characters?.find(role=>JSON.stringify(role).includes(src.split('?')[0]));if(candidate&&JSON.stringify(candidate).includes(src.split('?')[0])){c=candidate;p.set('upscale_project',String(data.project_id||data.local_id||data.title));p.set('upscale_character',String(c.id||c.character_id||c.name));angle=viewFor(c,src,image);p.set('role_view',angle);p.set('initial_prompt',typeof CharacterViewPrompts!=='undefined'?CharacterViewPrompts.features(c,angle==='portrait'):(c.prompt||c.description||''));p.set('view_prompt',[angle==='sheet'?'同一个角色的多视图设定图。':'只有一个角色、一个视角，背景没有其他人物或重复分身。',framing[angle],data.style||'',c.nonWhiteBackground?'均匀中性灰色背景。':'均匀纯白背景，无灰色底块、渐变或暗角。','柔和均匀光照，清晰细节，不要文字、水印或标志。'].join('\n'));if(c.specialReference){p.set('view_prompt','保持当前参考图片中的主体、结构与构图，按修改提示词编辑。');p.set('initial_prompt',c.specialImagePrompt||c.description||'');}const extra=({portrait:'全身，腰部，腿，鞋，远景',front:'裁头，裁脚，侧身，坐姿',left:'正面，四分之三侧面，朝右，看镜头',back:'正脸，侧脸，回头'})[angle]||'';p.set('initial_negative',typeof ImageNegativeSpec!=='undefined'?ImageNegativeSpec.negative({negative_prompt:[c.negativePrompt||'',extra].filter(Boolean).join('，')}):(c.negativePrompt||''));}}if(!c&&typeof data!=='undefined'){const scene=data.scenes?.find(s=>(s.sceneVersions||[]).some(v=>v.image_url?.split('?')[0]===src.split('?')[0]));if(scene){p.set('upscale_project',String(data.project_id||data.local_id||data.title));p.set('upscale_scene',String(scene.id||scene.scene_id));p.set('initial_prompt',scene.prompt||'');p.set('initial_negative',scene.negativePrompt||'');}}if(!c&&typeof data!=='undefined'){for(const shot of data.shots||[])for(const pos of ['first','last']){const selected=typeof ShotMethods!=='undefined'?ShotMethods.selected(shot,pos):null;if(selected?.image_url?.split('?')[0]===src.split('?')[0]){p.set('upscale_project',String(data.project_id));p.set('upscale_shot',String(shot.shot_id||shot.id));p.set('upscale_position',pos);p.delete('upscale_scene');}}}for(const[mode,a]of Object.entries(r.links)){a.hidden=mode==='text-image'&&!c;a.style.display=a.hidden?'none':'inline-flex';p.delete('tool_reference_image');p.delete('reference_name');const needsPortrait=mode==='image-image'&&c&&['front','left','back'].includes(angle),portrait=needsPortrait?(typeof currentIdentityPortrait==='function'?currentIdentityPortrait(c):c.identityPortrait):null;a.dataset.missingPortrait=needsPortrait&&!portrait?.image_url?'1':'';if(needsPortrait&&portrait?.image_url){p.set('tool_reference_image',portrait.image_url);p.set('reference_name',c.name+' · 大头照（身份参考）');}p.set('tool_mode',mode);const href='/tools.html?'+p;if(a.getAttribute('href')!==href)a.setAttribute('href',href);a.title=c?'在弹窗中生成，完成后替换当前角色图':'打开图片工具';a.setAttribute('aria-label',a.textContent.trim()+' '+title);}}}
function schedule(){if(!scheduled){scheduled=true;requestAnimationFrame(scan);}}new MutationObserver(schedule).observe(document.body,{childList:true,subtree:true,attributes:true,attributeFilter:['src','alt']});document.addEventListener('load',schedule,true);schedule();})();
